async function apiJson(url, options) {
  const res = await fetch(url, { credentials: "include", ...options });
  let data = null;
  try { data = await res.json(); } catch {}
  if (data?.pointEvent?.awarded) window.dispatchEvent(new CustomEvent("petgrow:points", { detail:{ amount:data.pointEvent.awarded,balance:data.pointEvent.balance,label:data.pointEvent.label||"PetPoint ì ë¦½" } }));
  if (data?.pointEvent?.spent) window.dispatchEvent(new CustomEvent("petgrow:points", { detail:{ amount:-data.pointEvent.spent,balance:data.pointEvent.balance,label:data.pointEvent.label||"PetPoint ì‚¬ìš©" } }));
  if (!res.ok) {
    const err = new Error((data && data.error) || `request failed (${res.status})`);
    err.status = res.status;
    throw err;
  }
  return data;
}
