function normalizeNickname(value = "") {
  return String(value).trim().replace(/\s+/g, " ");
}

function validateNicknameLocal(value = "") {
  const nickname = normalizeNickname(value);
  const reserved = ["admin","administrator","manager","moderator","ê´€ë¦¬ìž","petgrow","íŽ«ê·¸ë¡œìš°","ê³µì‹","official","staff","support","ê³ ê°ì„¼í„°"];
  const blocked = [
    /ì”¨ë°œ|ì‹œë°œ|ã……ã…‚|ë³‘ì‹ |ë¸…ì‹ |ê°œìƒˆë¼|ê°œìƒˆ|ì¢†|ì¡´ë‚˜|ì§€ëž„|êº¼ì ¸|ë‹¥ì³/i,
    /ì„¹ìŠ¤|sex|ì•¼ë™|porn|í¬ë¥´ë…¸|ìžìœ„|ë”¸ë”¸|ë³´ì§€|ìžì§€|ìŒëž€/i,
    /í˜ì˜¤|ë‚˜ì¹˜|nazi/i
  ];

  if (!nickname) return { ok:false, reason:"empty", message:"ë‹‰ë„¤ìž„ì„ ìž…ë ¥í•´ ì£¼ì„¸ìš”." };
  if (nickname.length < 2 || nickname.length > 8) {
    return { ok:false, reason:"length", message:"ë‹‰ë„¤ìž„ì€ 2~8ìž ì´ë‚´ë¡œ ìž…ë ¥í•´ ì£¼ì„¸ìš”." };
  }
  if (/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/.test(nickname) || /(?:01[016789])[-\s]?\d{3,4}[-\s]?\d{4}/.test(nickname)) {
    return { ok:false, reason:"private", message:"ì „í™”ë²ˆí˜¸ë‚˜ ì´ë©”ì¼ì€ ë‹‰ë„¤ìž„ìœ¼ë¡œ ì‚¬ìš©í•  ìˆ˜ ì—†ì–´ìš”." };
  }
  if (reserved.some((word) => nickname.toLowerCase().includes(word.toLowerCase()))) {
    return { ok:false, reason:"reserved", message:"ìš´ì˜ìžë‚˜ ê³µì‹ ê³„ì •ìœ¼ë¡œ ì˜¤í•´í•  ìˆ˜ ìžˆëŠ” ë‹‰ë„¤ìž„ì€ ì‚¬ìš©í•  ìˆ˜ ì—†ì–´ìš”." };
  }
  const compact = nickname.replace(/\s/g, "");
  if (blocked.some((rule) => rule.test(compact))) {
    return { ok:false, reason:"blocked", message:"ì‚¬ìš©í•  ìˆ˜ ì—†ëŠ” í‘œí˜„ì´ í¬í•¨ëœ ë‹‰ë„¤ìž„ì´ì—ìš”. ë‹¤ë¥¸ ë‹‰ë„¤ìž„ì„ ì‚¬ìš©í•´ ì£¼ì„¸ìš”." };
  }
  return { ok:true, nickname };
}

